-- #348: keep the Cata phase id and phase group distinct. Their ids collide (e.g. 367 is both a
-- Phase.dbc id and a PhaseXPhaseGroup.dbc group), so collapsing them into PhaseId loses meaning.
-- Worlds imported before this change stored a group in PhaseId when the source had no phase id;
-- the loader moves group-only values to PhaseGroup. Colliding ids cannot be disambiguated from the
-- collapsed column, so the clean world must be rebuilt/rerun through build_clean_world.py, which
-- restores both columns from TDB.
ALTER TABLE `creature` ADD COLUMN `PhaseGroup` int unsigned NOT NULL DEFAULT '0' AFTER `PhaseId`;
ALTER TABLE `gameobject` ADD COLUMN `PhaseGroup` int unsigned NOT NULL DEFAULT '0' AFTER `PhaseId`;
ALTER TABLE `phase_area` ADD COLUMN `PhaseGroup` int unsigned NOT NULL DEFAULT '0' AFTER `PhaseId`;
ALTER TABLE `phase_area` DROP PRIMARY KEY, ADD PRIMARY KEY (`AreaId`,`PhaseId`,`PhaseGroup`);
-- Rows written before this change can carry a group in PhaseId; move the unambiguous group-only
-- ids, then the known scenario mapping. A colliding id from another source needs a rebuild.
UPDATE `phase_area` SET `PhaseGroup`=`PhaseId`, `PhaseId`=0
 WHERE `PhaseGroup`=0 AND `PhaseId` IN (
398, 403, 409, 410, 411, 412, 413, 414,
415, 416, 419, 420, 422, 423, 435, 436,
437, 439, 446, 447, 453, 454, 455, 456,
457, 458, 461, 462, 463, 464, 465, 466,
468, 469, 471, 472, 474, 475, 476, 477,
478, 479, 480, 481, 482, 483, 484, 489,
490, 491, 493, 494, 495, 498, 499, 500,
501, 502, 503, 504, 505, 506, 507, 508,
509, 510, 511, 512, 513, 514, 515, 516,
517, 518, 519, 520, 521, 522, 523, 524,
525, 526, 527, 528, 529, 530, 531, 532,
533, 534, 537, 538, 539, 540, 541, 542,
543, 544, 545, 546, 547, 548, 549, 550,
551, 552, 553, 554, 555, 556, 557, 558,
559, 560, 561, 562, 563, 564, 565, 566,
567, 568, 569, 570, 571, 572, 573, 574,
575, 576, 577, 578, 580, 581, 582, 583,
584, 585, 586, 587, 588, 589, 590, 594,
595, 601, 602, 604, 605, 606, 608, 609,
610, 612, 614, 615, 618, 619, 620, 636,
650, 655, 656);
UPDATE `phase_area` SET `PhaseGroup`=367, `PhaseId`=0
 WHERE `AreaId`=1519 AND `PhaseId`=367 AND `PhaseGroup`=0;
